                        workspace: spRepo.owner, repository: spRepo.repo,
                        state: 'merged'
                    }));
                    spMerged = Array.isArray(spM) ? spM : [];
                } catch (eMerged) { /* merged lane empty this tick */ }
                // v3: ALL open issues in one search call — feeds both the
                // development lane (agent:dev) and the backlog section
                // (in_dev / queued / blocked / inbox, see factoryState).
                var spIssues = [];
                try {
                    var spD = mcpParse(github_search_issues({
                        query: 'repo:' + spFull + ' is:issue is:open'
                    }));
                    spIssues = Array.isArray(spD) ? spD :
                        ((spD && (spD.items || spD.data)) || []);
                } catch (eDevs) { /* development + backlog empty this tick */ }
                // v3: OPTIONAL per-leg token usage — LOCAL first (factories
                // whose legs drop a keyed JSON file in the tick's checkout,
                // statePublish.tokensFile), factory-data branch fallback
                // (gh-781: data/fa-tokens.json, the leg-side producer's
                // publish — completes the pipeline the moment the producer
                // lands). Any miss on EITHER source just publishes
                // token-less cards (board renders "—"); the branch fetch
                // happens only when the local file yields no map. The
                // winning source rides the 🪙 provenance line below — a
                // persistent miss (mis-typed tag, revoked Contents scope)
                // must stay distinguishable from "producer hasn't landed".
                var spTokens = factoryStateModule.readTokensFile(
                    (spCfg && spCfg.tokensFile) ||
                        factoryStateModule.DEFAULT_TOKENS_FILE,
                    function (p) { return file_read({ path: p }); });
                var spTokensSrc = spTokens ? 'local' : 'none';
                if (!spTokens) {
                    spTokens = factoryStateModule.fetchTokensFromBranch(
                        spFull, spCfg,
                        function (a) { return cli_execute_command(a); });
                    if (spTokens) spTokensSrc = 'branch';
                }
                var spPrev = factoryStateModule.fetchPreviousState(
                    spFull, spCfg, function (a) {
                        return cli_execute_command(a);
                    });
                var spState = factoryStateModule.buildFactoryState({
                    repoInfo: spRepo,
                    prs: spPrList,
                    mergedPrs: spMerged,
                    issues: spIssues,
                    machineAuthor: machineAuthorModule.resolveMachineAuthor(
                        RUN_JOB_PARAMS, effectiveConfig),
                    tokens: spTokens,
                    runs: spRunList,
                    checkNames: validationCheckNames() || [],
                    // gh-816: the lane writer must know which workflow is
                    // the machine's own validation — its dispatches are
                    // real cites, every other dispatch is a side-run leg
                    // (auxiliary, never the discharge cite). Same
                    // precedence chain as dispatchCiWorkflow and the five
                    // sibling sites above: rule.ciWorkflow >
                    // jobParams.ciWorkflow > default (gh-816 rework
                    // thread 1 — forwarding only the jobParams knob
                    // misclassified per-rule validation dispatches as
                    // side-run legs: no cite, dead pr_validation lane).
                    ciWorkflow: rule.ciWorkflow ||
                        ((RUN_JOB_PARAMS || {}).ciWorkflow) || 'quality.yml',
                    prev: spPrev,
                    dryRun: DRY,
                    processed: processedKeys,
                    // gh-806: this tick's rework latch rides the snapshot —
                    // the next tick's armer consults what this tick armed.
                    reworkInFlight: tickReworkLatch ? tickReworkLatch.map : {},
                    legWorkflow: reworkLatchModule.DEFAULT_LEG_WORKFLOW
                });
                var spUrl = factoryStateModule.publishFactoryState(
                    spState, spCfg, function (args) {
                        // MUST return: publishFactoryState probes the
                        // existing-file sha through this lambda — without
                        // the return the probe yields undefined, the PUT
                        // goes out sha-less and every update 422s
                        // ("sha wasn't supplied") after the first create.
                        return cli_execute_command(args);
                    });
                console.log('  📡 factory state published → ' + spUrl);
                // 🪙 provenance (rework pr-783 thread 3): which source fed
                // card.tokens this tick — local file, branch, or none. One
                // sibling line next to 📡, ALWAYS logged: pre-producer the
                // branch 404s every tick, so per-miss warns would just fill
                // the log with noise; a single grep-able line does not.
                console.log('  🪙 tokens: ' +
                    factoryStateModule.tokensLegCount(spTokens) +
                    ' legs (' + spTokensSrc + ')');
                try {
                    var hUrl = factoryStateModule.updateHistory(
                        spState, spCfg, function (a) {
                            return cli_execute_command(a);
                        });
                    console.log('  🕘 factory state history updated → ' + hUrl);
                } catch (eHist) {
                    // history is a board affordance — never fail the tick
                    console.warn('  ⚠️  factory state history failed: ' +
                                 (eHist.message || eHist));
                }
            }
        } catch (ePub) {
            console.warn('  ⚠️  factory state publish failed: ' +
                         (ePub.message || ePub));
        }
    }

    return { processedKeys: processedKeys, skippedKeys: skippedKeys };
}

// ─── Main ─────────────────────────────────────────────────────────────────────

