      g.rounds += 1;
      if (g.from == null && e.at != null) g.from = e.at;
      if (durs[i] != null) g.totalMs += durs[i];
      if (g.rounds > 1) {                           // re-visit = rework round
        g.reworkRounds += 1;
        if (durs[i] != null) g.reworkMs += durs[i];
