  });

  test('token rows keyed by issue attach to backlog cards', function () {
    var st = fsModule.buildFactoryState({
      repoInfo: { owner: 'o', repo: 'r' }, now: NOW, prs: [], runs: [],
      machineAuthor: 'ai-teammate',
