                github: { prList: PR31 },
                onCliExecute: branchServes(payload)
            });
            var card = run.state.lanes.pr_created.filter(function (c) { return c.pr === 31; })[0];
            assert.equal(card.tokens, undefined,
                'payload ' + payload + ' → token-less card');
