  // number is which lane, so the header contradicts the repo at a glance)
  var LANE_SHORT = {
    development: 'dev', pr_created: 'pr', pr_validation: 'ci',
    review: 'review', approved_queue: 'queue', validating: 'mutex',
    merged_recent: 'merged'
