            github: { prList: PR31 },
            onCliExecute: branchServes(BRANCH_TOKENS)
        });
        assert.ok(run.sm.capturedLogs.some(function (l) {
            return l.indexOf('🪙 tokens: 2 legs (branch)') !== -1;
