function parseModelPricing(parsed) {
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
    var rates = Object.create(null); // model ids come from snapshots — prototype-safe
    ... for each key !== 'default': value must be an object (non-array) with finite numeric `input` and `output` (>= 0); cacheRead optional numeric (default 0). Invalid entries are SKIPPED (tolerant), not fatal? Hmm — AC1: "bad JSON ⇒ tick warns, board renders tokens-only". "Bad JSON" = parse failure or shape garbage. Per-entry tolerance: skip invalid entries, keep valid ones — more resilient. But wait: what does "malformed-config tolerance" mean for tests — I'll test: top-level garbage → null; individual bad entries skipped; missing rates → null cost.
    Actually — think again about strictness. If entry is `{input: "3", output: 15}` (string input) — tolerate +coercion? `+v` then isFinite. I'll coerce numerics.
    var def = parsed.default — if null/absent → null; if valid entry shape → rates.
    Return { rates: rates, defaultRates: def, models: count } — but must require at least something? An empty `{}` file → rates {} with defaultRates null — valid but useless; cost omitted everywhere. That's fine (tolerant). Hmm, but readModelPricing returns null for `null` parse. Let me keep: parseModelPricing returns the pricing object for any object-shaped input, null otherwise.
}

function readModelPricing(path, readFn) {
    if (!path || typeof readFn !== 'function') return null;
    try {
        return parseModelPricing(JSON.parse(String(readFn(path) || '')));
    } catch (e) {
        return null;
    }

function ratesFor(pricing, model) {
    if (!pricing || !model) return (pricing && pricing.defaultRates) || null;  // hmm...
