                JSON.stringify(str) + ' should not contain ' + JSON.stringify(substr)
            );
        }
    },

    throws: function(fn, msg) {
        var threw = false;
        try { fn(); } catch (e) { threw = true; }
        if (!threw) {
            throw new Error(msg || 'expected function to throw but it did not');
        }
    },

    doesNotThrow: function(fn, msg) {
        try {
