      { leg: 'c', at: 't', prompt: 1, completion: 1, model: '' }
    ]);
    assert.equal(rows[0].model, null, 'absent → null');
    assert.equal(rows[1].model, null, 'null → null');
    assert.equal(rows[2].model, null, 'empty string (upstream "model":""") → null');
