{"newText":"  // compact token count: 940 · 115.9k · 1.2M (card chips + flow strip)
  function fmtK(n) {
    if (n == null || isNaN(n)) return '—';
    if (n >= 1e6) return (Math.round(n / 1e5) / 10) + 'M';
    if (n >= 1e3) return (Math.round(n / 100) / 10) + 'k';
    return String(n);
  }

  // USD for the gh-825 pricing surfaces: a leg is often a fraction of a
  // cent, so sub-cent values keep 4 decimals ($0.0032) while everything
  // above renders as cents ($12.34). Numeric only — never a NaN.
  function fmtUsd(n) {
    if (n == null || isNaN(n)) return '';
    if (n > 0 && n < 0.01) return '$' + n.toFixed(4);
    return '$' + n.toFixed(2);
  }","oldText":"  // compact token count: 940 · 115.9k · 1.2M (card chips + flow strip)
