    return String(n);
  }","path":"site/factory/app.js"}

{"newText":"  function tokChipHtml(c) {
    var t = FLOW.tokenTotals(c);
    if (!t) return '';
    var legs = Object.keys(t.legs).map(function (k) {
      return k + ' ' + fmtK(t.legs[k].total);
    }).join(', ');
